package retry

// Retry calls fn until it returns nil, at most 3 times, and returns the last error.
func Retry(fn func() error) error {
	var err error
	for i := 0; i < 3; i++ {
		if err = fn(); err == nil {
			return nil
		}
	}
	return err
}

