package retry

import (
	"errors"
	"testing"
)

func TestRetry_StopsAtThree(t *testing.T) {
	n := 0
	err := Retry(func() error { n++; return errors.New("no") })
	if err == nil || n != 3 {
		t.Fatalf("n=%d err=%v", n, err)
	}
}
